class BrowserReceiverServer(private val context:Context){
private val running=AtomicBoolean(false);private val pool=Executors.newCachedThreadPool();private var server:ServerSocket?=null;@Volatile private var snapshot=ReceiverSnapshot();private val clients=ConcurrentHashMap<String,Long>()
data class ReceiverSnapshot(val reference:String="",val text:String="",val translation:String="",val kind:String="",val black:Boolean=false,val background:String="",val overlay:Float=.38f,val textSize:Int=32,val autoFit:Boolean=true,val revision:Long=0)
fun isRunning()=running.get();fun currentAddress(port:Int=8787)=if(running.get())mainAddress(port)else null;fun mainAddress(port:Int=8787)=address(port)?.let{"$it/m"};fun foldbackAddress(port:Int=8787)=address(port)?.let{"$it/f"}
fun connectedClients():Int{pruneClients();return clients.size}
fun connectedMainClients():Int{pruneClients();return clients.keys.count{it.startsWith("/main:")}}
fun connectedFoldbackClients():Int{pruneClients();return clients.keys.count{it.startsWith("/foldback:")}}
fun assignedBus():PresentationBus=OutputRouting.busFor(OutputTransport.BROWSER)
fun start(port:Int=8787):String?{if(running.get())return mainAddress(port);return runCatching{server=ServerSocket(port).also{ss->running.set(true);pool.execute{while(running.get())runCatching{ss.accept()}.getOrNull()?.let{c->pool.execute{serve(c)}}}};mainAddress(port)}.getOrNull()}
fun publish(slide:PresentationSlide?,black:Boolean,theme:BackgroundTheme?=null,textSize:Int=32,autoFit:Boolean=true){snapshot=ReceiverSnapshot(slide?.reference.orEmpty(),slide?.text.orEmpty(),slide?.translation.orEmpty(),slide?.kind.orEmpty(),black,theme?.localPath.orEmpty(),theme?.overlay?:.38f,textSize,autoFit,snapshot.revision+1)}
fun stop(){running.set(false);clients.clear();runCatching{server?.close()};server=null};private fun pruneClients(){val cutoff=System.currentTimeMillis()-5000;clients.entries.removeIf{it.value<cutoff}};private fun heartbeat(id:String,remote:String){clients[if(id.isBlank())remote else id]=System.currentTimeMillis();pruneClients()}
private fun serve(socket:Socket)=socket.use{s->s.soTimeout=2500;val reader=BufferedReader(InputStreamReader(s.getInputStream()));val first=reader.readLine().orEmpty();var line:String?;do{line=reader.readLine()}while(!line.isNullOrEmpty());val raw=first.split(' ').getOrNull(1)?:"/";val query=raw.substringAfter('?',"");val path=URLDecoder.decode(raw.substringBefore('?'),"UTF-8");if(path.startsWith("/heartbeat")){val id=query.split('&').firstOrNull{it.startsWith("id=")}?.substringAfter('=')?.let{URLDecoder.decode(it,"UTF-8")}.orEmpty();heartbeat(id,s.inetAddress?.hostAddress.orEmpty());write(s,"application/json; charset=utf-8",JSONObject().put("connected",connectedClients()).put("main",connectedMainClients()).put("foldback",connectedFoldbackClients()).toString().toByteArray(),false);return@use};if(path.startsWith("/background")){val f=File(snapshot.background);if(f.exists()){write(s,contentType(f),f.readBytes(),true);return@use}};val foldback=path.startsWith("/foldback");val stateRequest=path.endsWith("/state")||path=="/state";val body=if(stateRequest)stateJson(if(foldback)PresentationBus.FOLDBACK else PresentationBus.MAIN) else receiverHtml(if(foldback)"/foldback" else "/main");write(s,if(stateRequest)"application/json; charset=utf-8" else "text/html; charset=utf-8",body.toByteArray(),false)}
private fun contentType(f:File)=when(f.extension.lowercase()){ "png"->"image/png";"webp"->"image/webp";"gif"->"image/gif";"mp4"->"video/mp4";"webm"->"video/webm";else->"image/jpeg"};private fun write(s:Socket,type:String,bytes:ByteArray,cache:Boolean){val out=s.getOutputStream();out.write("HTTP/1.1 200 OK\r\nContent-Type: $type\r\nContent-Length: ${bytes.size}\r\nCache-Control: ${if(cache)"private, max-age=86400" else "no-store"}\r\nConnection: close\r\n\r\n".toByteArray());out.write(bytes);out.flush()}
private fun stateJson(bus:PresentationBus):String{val s=snapshot;return JSONObject().apply{put("bus",bus.name.lowercase());put("black",s.black);put("hasBackground",s.background.isNotBlank()&&File(s.background).exists());put("backgroundKey",if(s.background.isBlank())"" else File(s.background).absolutePath.hashCode().toString());put("backgroundVideo",s.background.lowercase().let{it.endsWith(".mp4")||it.endsWith(".webm")});put("overlay",s.overlay);put("textSize",s.textSize);put("autoFit",s.autoFit);put("revision",s.revision);if(bus==PresentationBus.FOLDBACK){FoldbackTimer.refresh();val model=ScriptureFoldbackRenderer.render();put("reference",model?.currentReference?:s.reference);put("text",model?.currentText?:s.text);put("translation",model?.translation?:s.translation);put("nextReference",model?.nextReference.orEmpty());put("nextText",model?.nextText.orEmpty());put("endLabel",model?.endLabel.orEmpty());put("stageTimer",if(FoldbackTimer.running||FoldbackTimer.remainingSeconds!=FoldbackTimer.configuredSeconds)FoldbackTimer.display() else "");put("stageTimerRunning",FoldbackTimer.running);put("stageTimerOvertime",FoldbackTimer.remainingSeconds<0L);put("clockEnabled",FoldbackWidgetState.layout.clock.enabled);put("clock24Hour",FoldbackWidgetState.layout.clock.use24Hour);put("clockSeconds",FoldbackWidgetState.layout.clock.showSeconds);put("clockAnchor",FoldbackWidgetState.layout.clock.anchor.name);put("alertEnabled",FoldbackWidgetState.layout.alert.enabled);put("alertMessage",FoldbackWidgetState.layout.alert.message);put("kind","foldback")}else{put("reference",s.reference);put("text",s.text);put("translation",s.translation);put("kind",s.kind);if(s.kind=="countdown"){CongregationTimer.refresh();put("countdown",true);put("countdownRemaining",CongregationTimer.remainingSeconds);put("countdownRunning",CongregationTimer.running)}}}.toString()}
private fun receiverHtml(base:String)="""<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><style>html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#000;color:#fff;font-family:Arial,sans-serif}#bg,#vid,#shade,#stage{position:fixed;inset:0}#bg{background-size:cover;background-position:center}#vid{width:100%;height:100%;object-fit:cover;display:none}#stage{box-sizing:border-box;display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center;padding:5vh 6vw}.ref{font-size:2.5vw;font-weight:700;margin-bottom:2vh}.body{line-height:1.16;font-weight:600;max-width:92vw;white-space:pre-wrap;transition:opacity .10s ease}.tr,.next{font-size:1.7vw;margin-top:2vh;white-space:pre-wrap;transition:opacity .10s ease}.timer{position:fixed;top:3vh;left:3vw;font-size:3vw;font-weight:900}.clock{position:fixed;top:3vh;right:3vw;font-size:3vw;font-weight:800}.alert{position:fixed;left:0;right:0;bottom:3vh;background:rgba(0,0,0,.8);padding:1.5vh 2vw;font-size:2vw;white-space:nowrap;overflow:hidden}</style></head><body><div id='bg'></div><video id='vid' muted loop playsinline></video><div id='shade'></div><div id='stage'><div id='ref' class='ref'></div><div id='body' class='body'></div><div id='tr' class='tr'></div><div id='next' class='next'></div></div><div id='timer' class='timer'></div><div id='clock' class='clock'></div><div id='alert' class='alert'></div><script>const BASE='$base',refEl=document.getElementById('ref'),bodyEl=document.getElementById('body'),trEl=document.getElementById('tr'),nextEl=document.getElementById('next');let rev=-1,w=null,bgKey='',clientKey='kzClientId:'+BASE,clientId=sessionStorage.getItem(clientKey)||(crypto.randomUUID?crypto.randomUUID():Date.now()+'-'+Math.random()),countdown=null,countdownTimer=null,clockTimer=null,last={};sessionStorage.setItem(clientKey,clientId);async function awake(){try{if('wakeLock'in navigator&&!w){w=await navigator.wakeLock.request('screen');w.onrelease=()=>w=null}}catch(e){}}async function beat(){try{await fetch('/heartbeat?id='+encodeURIComponent(BASE+':'+clientId)+'&t='+Date.now(),{cache:'no-store'})}catch(e){}}function fit(el,want,auto){let px=want*innerWidth/1000;el.style.fontSize=px+'px';if(!auto)return;let min=Math.max(12,innerHeight*.018),guard=0;while((el.scrollHeight>innerHeight*.70||el.scrollWidth>innerWidth*.9)&&px>min&&guard++<300){px-=1;el.style.fontSize=px+'px'}}function setBackground(s){let bg=document.getElementById('bg'),v=document.getElementById('vid');if(!s.hasBackground){if(bgKey){bg.style.backgroundImage='none';if(!v.paused)v.pause();v.style.display='none';v.removeAttribute('src');bgKey=''}return}if(bgKey===s.backgroundKey)return;bgKey=s.backgroundKey;if(s.backgroundVideo){bg.style.backgroundImage='none';v.src='/background?k='+encodeURIComponent(bgKey);v.style.display='block';v.play().catch(()=>{})}else{if(!v.paused)v.pause();v.style.display='none';v.removeAttribute('src');bg.style.backgroundImage='url(/background?k='+encodeURIComponent(bgKey)+')'}}function setText(el,value){value=value||'';if(el.textContent!==value)el.textContent=value}function renderCountdown(){if(!countdown)return;let elapsed=countdown.running?Math.floor((Date.now()-countdown.receivedAt)/1000):0,sec=Math.max(0,countdown.remaining-elapsed),h=Math.floor(sec/3600),m=Math.floor((sec%3600)/60),ss=String(sec%60).padStart(2,'0'),display=h>0?String(h).padStart(2,'0')+':'+String(m).padStart(2,'0')+':'+ss:String(m).padStart(2,'0')+':'+ss;setText(bodyEl,'SERVICE BEGINS IN\n\n'+display)}function setCountdown(s){let active=!!s.countdown;if(!active){countdown=null;if(countdownTimer){clearInterval(countdownTimer);countdownTimer=null}return}countdown={remaining:s.countdownRemaining,running:s.countdownRunning,receivedAt:Date.now()};if(!countdownTimer)countdownTimer=setInterval(renderCountdown,250);renderCountdown()}function setFoldback(s){let c=document.getElementById('clock'),a=document.getElementById('alert'),t=document.getElementById('timer');if(clockTimer){clearInterval(clockTimer);clockTimer=null}if(s.bus==='foldback'&&s.clockEnabled){let draw=()=>{let d=new Date();c.textContent=d.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',second:s.clockSeconds?'2-digit':undefined,hour12:!s.clock24Hour})};draw();clockTimer=setInterval(draw,1000)}else setText(c,'');setText(a,s.bus==='foldback'&&s.alertEnabled?s.alertMessage:'');setText(t,s.bus==='foldback'?(s.stageTimer||''):'')}function clearCanvas(){setText(refEl,'');setText(bodyEl,'');setText(trEl,'');setText(nextEl,'')}async function tick(){try{let s=await(await fetch(BASE+'/state?'+Date.now(),{cache:'no-store'})).json();let dynamic=s.bus==='foldback'||s.countdown;if(s.revision===rev&&!dynamic)return;rev=s.revision;awake();setBackground(s);setFoldback(s);let sh=document.getElementById('shade');if(s.black){sh.style.background='#000';clearCanvas();setCountdown({countdown:false});return}sh.style.background='rgba(0,0,0,'+(s.hasBackground?s.overlay:1)+')';setText(refEl,s.reference);if(!s.countdown)setText(bodyEl,s.text);setText(trEl,s.translation);setText(nextEl,s.nextReference?('NEXT  '+s.nextReference+'\n'+(s.nextText||'')):(s.endLabel||''));setCountdown(s);requestAnimationFrame(()=>fit(bodyEl,s.textSize,s.autoFit));last=s}catch(e){}}document.addEventListener('visibilitychange',()=>{awake();if(!document.hidden){beat();tick()}});document.addEventListener('click',awake);window.addEventListener('online',()=>{beat();tick()});awake();beat();setInterval(beat,2000);setInterval(tick,250);tick()</script></body></html>"""
private fun address(port:Int)=localIpv4()?.let{"http://$it:$port"};private fun localIpv4():String?{val interfaces=Collections.list(NetworkInterface.getNetworkInterfaces());return interfaces.asSequence().flatMap{Collections.list(it.inetAddresses).asSequence()}.filterIsInstance<Inet4Address>().firstOrNull{!it.isLoopbackAddress&&it.isSiteLocalAddress}?.hostAddress?:runCatching{val wifi=context.applicationContext.getSystemService(Context.WIFI_SERVICE)as WifiManager;val ip=wifi.connectionInfo.ipAddress;if(ip==0)null else "%d.%d.%d.%d".format(ip and 255,ip shr 8 and 255,ip shr 16 and 255,ip shr 24 and 255)}.getOrNull()}}
